#!/usr/bin/env python3
"""Validate inputs and freeze a predeclared volatility-managed portfolio grid."""
from __future__ import annotations
import hashlib,json,sys
from datetime import datetime,timezone
from pathlib import Path
import polars as pl
ROOT=Path(__file__).resolve().parents[3]; R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation')); import registry
MIN=60_000_000_000
assets={}
for asset in ('BTC','ETH'):
 paths=[ROOT/f'data/normalized/binance/{asset}/binance_{asset}_20240916T000000Z_20250916T000000Z_transfer_20261001/spot_bars.parquet',ROOT/f'data/normalized/binance/{asset}/binance_{asset}_20250916T000000Z_20260916T000000Z_archive_20260929/spot_bars.parquet']
 parts=[]
 for p in paths:
  f=pl.read_parquet(p,columns=['open_ts','available_ts','open','close','base_volume','quote_volume','is_closed'])
  assert f.height==365*1440 and f['is_closed'].all() and f['open_ts'].is_sorted()
  assert (f['open_ts'].diff().drop_nulls()==MIN).all() and (f['available_ts']-f['open_ts']==MIN).all()
  assert (f['open']>0).all() and (f['close']>0).all() and (f['quote_volume']>=0).all()
  parts.append({'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'bars':f.height,'first_open_ns':int(f['open_ts'][0]),'last_open_ns':int(f['open_ts'][-1])})
 # Confirm adjoining years and exact calendar start/end without creating any performance results.
 assert parts[1]['first_open_ns']==parts[0]['last_open_ns']+MIN
 assets[asset]={'files':parts,'total_1m_rows':365*1440*2,'series_start_utc':'2024-09-16T00:00:00Z','series_end_exclusive_utc':'2026-09-16T00:00:00Z'}
filters=json.loads((R/'exchange_filters.json').read_text())
assert filters['raw_sha256']==hashlib.sha256((R/'exchange_info_raw.json').read_bytes()).hexdigest()
assert set(filters['symbols'])=={'BTCUSDT','ETHUSDT'}
START='2025-09-19T00:01:00Z'; END='2026-09-14T00:01:00Z'
lookbacks=[20,60,120];targets=[0.20,0.30,0.40]
cost={'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'impact_model':'0.5 * sample stdev of previous 20 complete UTC daily log returns * sqrt(order quote budget / mean previous 20 complete UTC daily quote ADV)','maximum_ADV_participation':0.001,'multipliers':[1,2,3],'all_terms_scaled_together':True,'cash_yield':0}
logic={'family_hypothesis':'Monthly volatility-managed, long-only BTC/ETH cash sleeves may reduce exposure during high-volatility periods without trend forecasting. The test does not assume positive alpha.','signal':'At the initial OOS timestamp and then only on the first UTC day of each calendar month, estimate sample stdev of the last L fully closed daily log returns, ending at the previous UTC daily close. Compute realized annual volatility = daily stdev * sqrt(365). Set the sleeve target fraction to min(1, (target annual volatility / realized annual volatility)^2). No leverage; target fraction is measured against that sleeve’s own current NAV.','sizing':'Each 2,000 USDT configuration has an independent initial BTC sleeve of 1,000 USDT and ETH sleeve of 1,000 USDT (raw initial weights 0.5/0.5). Each sleeve holds BTC or ETH plus residual USDT. It cannot transfer funds, rebalance against the other sleeve, or earn cash yield. Monthly exposure changes trade only the difference needed to reach the target fraction.','execution':'Use only fully closed daily bars. Initial OOS signal is available at 2025-09-19T00:00:00Z and trades at the observed historical 1m open at 00:01 UTC. Subsequent decisions occur at the 1m open at 00:01 on each first UTC day of the month after its previous daily candle closes. Terminal positions are liquidated at 2026-09-14T00:01:00Z. These are archived historical backtest references, never current paper10 fills.','costs':'Each partial rebalance applies fee, estimated half-spread, slippage, square-root impact, exchange tick/lot/notional and percent-price filters; order participation is capped at 0.1% of lagged 20-day quote ADV. Cost assumptions scale by 1x/2x/3x. Below-minimum legal orders are skipped and recorded, not imputed.'}
failure={'positive_net_return_all_cost_scenes':True,'positive_1x_folds_minimum':8,'folds':12,'fold_days':30,'max_3x_sampled_drawdown_pct':25,'local_3x_neighbor_positive_fraction_minimum':0.60,'local_neighbor_definition':'At most one adjacent value on each frozen lookback and target-volatility grid axis; center included.','minimum_1x_rebalances':4,'gross_reference_pnl_to_1x_cost_minimum':2.5,'no_rejected_or_capacity_orders':True,'terminal_flat_after_costed_exit':True,'benchmarks':'Matched 50/50 BTC/ETH buy-and-hold and zero-yield cash on the same execution interval; comparator is not eligible to pass.'}
plan={'round':R.name,'frozen_at_utc':datetime.now(timezone.utc).isoformat().replace('+00:00','Z'),'status':'frozen_before_evaluation','source_repository_commit':__import__('subprocess').check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'direction':'monthly BTC/ETH volatility-managed exposure with independent long-only USDT sleeves','assumption':'Exposure scaled inversely to lagged realized variance may improve downside and return consistency compared with static exposure; all parameters are prespecified and this familiar rule is not assumed profitable.','prior_work':'No exact family/config fingerprint exists in the merged registry. Earlier channel-volatility-ceiling strategies gate signals; this batch has no directional entry/exit signal and instead changes the exposure of both independent buy-and-hold sleeves monthly. Earlier 4h momentum, relative-strength rotation, ratio mean reversion and volatility compression were rejected.','source_literature':[{'citation':'Moreira & Muir, Volatility Managed Portfolios, NBER Working Paper 22208 (2016).','url':'https://www.nber.org/papers/w22208','accessed_utc':'2026-10-13','scope':'Inverse-variance scaling motivation in equity portfolios, not evidence for BTC/ETH monthly spot sleeves.'}],'data':{'exchange':'Binance spot archived 1m OHLCV, aggregated only to complete UTC daily candles for signals','assets':assets,'oos_start_utc':START,'terminal_execution_utc':END,'oos_days':360,'fold_count':12,'fold_days':30,'history_reused':True,'note':'This 2025-09-19..2026-09-14 window is heavily reused in prior research; it is not an untouched holdout. No parameters are trained.'},'portfolio':{'capital_usdt_per_configuration':2000,'raw_initial_weights':[0.5,0.5],'meaning':'Independent BTC and ETH cash sleeves of 1,000 USDT each; no cross-sleeve transfers or rebalancing. Monthly target exposure applies within each sleeve.','leverage':False,'shorts':False,'cash_yield':0},'rule':logic,'grid':{'realized_vol_lookback_days':lookbacks,'target_annual_volatility':[0.20,0.30,0.40],'rebalance_schedule':'First OOS decision then first UTC calendar day 00:01; no intermediate trades.','local_sensitivity':'Full 3x3 grid; neighbor on each axis means one adjacent grid value.'},'cost_model':cost,'exchange_snapshot':{'path':'research/experiments/'+R.name+'/exchange_filters.json','raw_path':'research/experiments/'+R.name+'/exchange_info_raw.json','received_at_utc':filters['snapshot_at_utc'],'raw_sha256':filters['raw_sha256']},'failure_criteria':failure,'execution_limitations':'No historical L2 or queue data. Historical 1m opens are used only for this backtest; cost model is estimated and not a fill guarantee.'}
plan['_sha256']=registry.digest(plan)
(R/'plan.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
batch=[]
for L in lookbacks:
 for target in targets:
  name=f'volmanaged_L{L}_V{int(target*100):02d}'
  spec={'kind':'strategy','family':'spot-monthly-volatility-managed-sleeves','market':'spot','universe':['BTC/USDT','ETH/USDT'],'timeframe':'1d','logic':logic,'parameters':{'realized_vol_lookback_days':L,'target_annual_volatility':target,'rebalance_schedule':'initial OOS execution then first UTC day each month at 00:01; no intermediate rebalance','initial_capital_usdt':2000,'raw_initial_asset_weights':[0.5,0.5],'per_asset_initial_cash_usdt':1000,'start_utc':START,'end_exclusive_utc':END,'fold_count':12,'fold_days':30,'cost_multipliers':[1,2,3],'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'maximum_ADV_participation':0.001,'exchange_filters_sha256':filters['raw_sha256']},'name':name,'validation_plan':f'research/experiments/{R.name}/plan.json'}
  p=R/'specs'/f'{name}.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n');batch.append({'name':name,'spec':str(p.relative_to(ROOT)),'role':'candidate'})
benchmark={'kind':'strategy','family':'spot-monthly-volatility-managed-comparator','market':'spot','universe':['BTC/USDT','ETH/USDT'],'timeframe':'1d','logic':{'benchmark':'Static 50/50 initial BTC/ETH capital, buy once at the initial 00:01 UTC reference and hold until terminal costed liquidation. No interim rebalancing, leverage, cash yield or transfers.','execution':'At 2025-09-19T00:01:00Z buy each independent 1,000 USDT sleeve once, then costed terminal exits at 2026-09-14T00:01:00Z. No interim trades.','costs':logic['costs']},'parameters':{'initial_capital_usdt':2000,'raw_initial_weights':[0.5,0.5],'per_asset_initial_cash_usdt':1000,'start_utc':START,'end_exclusive_utc':END,'cost_multipliers':[1,2,3],'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'maximum_ADV_participation':0.001,'exchange_filters_sha256':filters['raw_sha256']},'name':'hold_360d_BTC_ETH_50_50_monthly_volmanaged','validation_plan':f'research/experiments/{R.name}/plan.json'}
p=R/'specs'/'hold_360d_BTC_ETH_50_50_monthly_volmanaged.json';p.write_text(json.dumps(benchmark,indent=2,ensure_ascii=False)+'\n');batch.append({'name':benchmark['name'],'spec':str(p.relative_to(ROOT)),'role':'comparator'})
(R/'batch.json').write_text(json.dumps(batch,indent=2,ensure_ascii=False)+'\n')
records=registry.read_records(ROOT/'research/automation/registry.jsonl');seen=set()
for row in batch:
 s=json.loads((ROOT/row['spec']).read_text());fp=registry.fingerprint(s);assert fp not in seen;seen.add(fp)
 prior=records.get(fp);assert not (prior and prior.get('result_available') is True),f"completed duplicate {row['name']}"
print(json.dumps({'plan_sha256':hashlib.sha256((R/'plan.json').read_bytes()).hexdigest(),'candidates':9,'comparators':1,'source_data_hashes':{a:[x['sha256'] for x in v['files']] for a,v in assets.items()},'fingerprints':len(seen),'frozen':True},ensure_ascii=False))
